  border-radius: 8px;\n            background-color: rgba(255, 140, 0, 0.1);\n            border: 1px solid var(--border-color);\n            display: none;\n        }\n        \n        .solution-steps {\n            font-family: monospace;\n            margin-top: 10px;\n            white-space: pre-wrap;\n        }\n        \n        .education {\n            width: 100%;\n            background-color: var(--input-bg);\n            border-radius: 8px;\n            padding: 20px;\n        }\n        \n        .education h2 {\n            margin-bottom: 15px;\n            background: linear-gradient(135deg, var(--orange-light), var(--orange-dark));\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            font-weight: 700;\n        }\n        \n        .education p {\n            margin-bottom: 15px;\n            line-height: 1.5;\n        }\n        \n        .letter-table {\n            width: 100%;\n            border-collapse: collapse;\n            margin: 15px 0;\n        }\n        \n        .letter-table th, .letter-table td {\n            padding: 10px;\n            text-align: center;\n            border: 1px solid var(--border-color);\n        }\n        \n        .letter-table th {\n            background: linear-gradient(135deg, var(--orange-light), var(--orange-dark));\n        }\n        \n        @keyframes fadeIn {\n            from { opacity: 0; transform: translateY(10px); }\n            to { opacity: 1; transform: translateY(0); }\n        }\n        \n        .fade-in {\n            animation: fadeIn 0.5s ease forwards;\n        }\n        \n        @keyframes glow {\n            0% { box-shadow: 0 0 5px var(--orange-dark); }\n            50% { box-shadow: 0 0 20px var(--orange-dark); }\n            100% { box-shadow: 0 0 5px var(--orange-dark); }\n        }\n        \n        .glow {\n            animation: glow 1.5s infinite;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"header\">\n        <h1>Numberology Game</h1>\n        <p>Test your numberology calculation skills</p>\n    </div>\n    \n    <div class=\"container\">\n        <div class=\"game-container\">\n            <h2>Calculate the Numberology Value</h2>\n            <p>Convert the word below to its numerology value using the letter-to-number table.</p>\n            \n            <div class=\"word-display\" id=\"word-to-calculate\">LOVE</div>\n            \n            <div class=\"input-container\">\n                <label for=\"answer-input\">Your Answer (1-9)</label>\n                <input \n                    type=\"number\" \n                    id=\"answer-input\" \n                    class=\"input-field\" \n                    placeholder=\"Enter a number from 1 to 9\" \n                    min=\"1\" \n                    max=\"9\"\n                >\n            </div>\n            \n            <button id=\"check-answer-btn\" class=\"button\">Check Answer</button>\n            \n            <div id=\"feedback\" class=\"feedback\"></div>\n            \n            <div id=\"solution\" class=\"solution\">\n                <p><strong>Correct Calculation:</strong></p>\n                <div id=\"solution-steps\" class=\"solution-steps\"></div>\n            </div>\n            \n            <div class=\"score-container\">\n                <div class=\"score-item\">\n                    <div class=\"score-label\">Correct</div>\n                    <div class=\"score-value\" id=\"correct-score\">0</div>\n                </div>\n                <div class=\"score-item\">\n                    <div class=\"score-label\">Attempts</div>\n                    <div class=\"score-value\" id=\"attempts-score\">0</div>\n                </div>\n                <div class=\"score-item\">\n                    <div class=\"score-label\">Accuracy</div>\n                    <div class=\"score-value\" id=\"accuracy-score\">0%</div>\n                </div>\n            </div>\n            \n            <button id=\"new-word-btn\" class=\"new-word-button\">Get New Word</button>\n        </div>\n        \n        <div class=\"education\">\n            <h2>How to Calculate Numberology Values</h2>\n            <p>In numerology, each letter is assigned a number from 1 to 9 based on the following pattern:</p>\n            \n            <table class=\"letter-table\">\n                <tr>\n                    <th>1</th>\n                    <th>2</th>\n                    <th>3</th>\n                    <th>4</th>\n                    <th>5</th>\n                    <th>6</th>\n                    <th>7</th>\n                    <th>8</th>\n                    <th>9</th>\n                </tr>\n                <tr>\n                    <td>A, J, S</td>\n                    <td>B, K, T</td>\n                    <td>C, L, U</td>\n                    <td>D, M, V</td>\n                    <td>E, N, W</td>\n                    <td>F, O, X</td>\n                    <td>G, P, Y</td>\n                    <td>H, Q, Z</td>\n                    <td>I, R</td>\n                </tr>\n            </table>\n            \n            <p>To calculate a word\'s numerology value:</p>\n            <ol>\n                <li>Convert each letter to its corresponding number</li>\n                <li>Add all the numbers together</li>\n                <li>If the sum is a two-digit number (or more), add those digits together</li>\n                <li>Continue this process until you get a single-digit number (1-9)</li>\n            </ol>\n            \n            <p>Example: \"LOVE\"</p>\n            <ul>\n                <li>L = 3 (L is in the 3rd column)</li>\n                <li>O = 6 (O is in the 6th column)</li>\n                <li>V = 4 (V is in the 4th column)</li>\n                <li>E = 5 (E is in the 5th column)</li>\n                <li>3 + 6 + 4 + 5 = 18</li>\n                <li>1 + 8 = 9</li>\n                <li>Final numerology value: 9</li>\n            </ul>\n        </div>\n    </div>\n    \n    <script>\n        const letterValues = {\n            \'A\': 1, \'J\': 1, \'S\': 1,\n            \'B\': 2, \'K\': 2, \'T\': 2,\n            \'C\': 3, \'L\': 3, \'U\': 3,\n            \'D\': 4, \'M\': 4, \'V\': 4,\n            \'E\': 5, \'N\': 5, \'W\': 5,\n            \'F\': 6, \'O\': 6, \'X\': 6,\n            \'G\': 7, \'P\': 7, \'Y\': 7,\n            \'H\': 8, \'Q\': 8, \'Z\': 8,\n            \'I\': 9, \'R\': 9\n        };\n        \n        // List of words for the game\n        const wordList = [\n            \"LOVE\", \"HAPPY\", \"SUNSHINE\", \"DREAM\", \"MAGIC\", \n            \"WISDOM\", \"PEACE\", \"DESTINY\", \"HARMONY\", \"FAITH\",\n            \"CREATIVE\", \"SUCCESS\", \"ABUNDANCE\", \"TRUTH\", \"POWER\",\n            \"FRIENDSHIP\", \"HEALTH\", \"FAMILY\", \"FREEDOM\", \"COURAGE\"\n        ];\n        \n        let currentWord = \"\";\n        let correctAnswer = 0;\n        let correctCount = 0;\n        let attemptCount = 0;\n        \n        function getLetterValue(letter) {\n            return letterValues[letter.toUpperCase()] || 0;\n        }\n        \n        function calculateNumerology(word) {\n            if (!word) return { value: 0, steps: [\"No word entered\"] };\n            \n            word = word.toUpperCase().replace(/[^A-Z]/g, \'\');\n            \n            let steps = [];\n            let letterCalcs = [];\n            \n            // Step 1: Convert each letter\n            for (let i = 0; i < word.length; i++) {\n                const letter = word[i];\n                const value = getLetterValue(letter);\n                letterCalcs.push(`\${letter} = \${value}`);\n            }\n            \n            steps.push(`Converting letters: \${letterCalcs.join(\', \')}`);\n            \n            // Step 2: Sum all numbers\n            const letterValues = word.split(\'\').map(letter => getLetterValue(letter));\n            const initialSum = letterValues.reduce((sum, value) => sum + value, 0);\n            \n            steps.push(`Adding all numbers: \${letterValues.join(\' + \')} = \${initialSum}`);\n            \n            // Step 3: Reduce to a single digit\n            let currentSum = initialSum;\n            \n            while (currentSum > 9) {\n                const digits = currentSum.toString().split(\'\').map(Number);\n                const newSum = digits.reduce((sum, digit) => sum + digit, 0);\n                steps.push(`Reducing \${currentSum}: \${digits.join(\' + \')} = \${newSum}`);\n                currentSum = newSum;\n            }\n            \n            steps.push(`Final numerology value: \${currentSum}`);\n            \n            return {\n                value: currentSum,\n                steps: steps\n            };\n        }\n        \n        function getRandomWord() {\n            const randomIndex = Math.floor(Math.random() * wordList.length);\n            return wordList[randomIndex];\n        }\n        \n        function setNewWord() {\n            currentWord = getRandomWord();\n            const result = calculateNumerology(currentWord);\n            correctAnswer = result.value;\n            \n            document.getElementById(\'word-to-calculate\').textContent = currentWord;\n            document.getElementById(\'answer-input\').value = \'\';\n            document.getElementById(\'feedback\').style.display = \'none\';\n            document.getElementById(\'solution\').style.display = \'none\';\n            \n            // Store solution for later\n            document.getElementById(\'solution-steps\').textContent = result.steps.join(\'\\n\');\n            \n            // Add glow effect to the new word\n            const wordElement = document.getElementById(\'word-to-calculate\');\n            wordElement.classList.remove(\'glow\');\n            void wordElement.offsetWidth; // Force reflow\n            wordElement.classList.add(\'glow\');\n        }\n        \n        function updateScores() {\n            document.getElementById(\'correct-score\').textContent = correctCount;\n            document.getElementById(\'attempts-score\').textContent = attemptCount;\n            \n            const accuracy = attemptCount > 0 ? Math.round((correctCount / attemptCount) * 100) : 0;\n            document.getElementById(\'accuracy-score\').textContent = `\${accuracy}%`;\n        }\n        \n        function checkAnswer() {\n            const userAnswer = parseInt(document.getElementById(\'answer-input\').value);\n            const feedbackElement = document.getElementById(\'feedback\');\n            \n            // Validate input\n            if (isNaN(userAnswer) || userAnswer < 1 || userAnswer > 9) {\n                feedbackElement.textContent = \'Please enter a number between 1 and 9\';\n                feedbackElement.className = \'feedback feedback-incorrect fade-in\';\n                feedbackElement.style.display = \'block\';\n                return;\n            }\n            \n            attemptCount++;\n            \n            // Check answer\n            if (userAnswer === correctAnswer) {\n                correctCount++;\n                feedbackElement.textContent = \'Correct! Well done!\';\n                feedbackElement.className = \'feedback feedback-correct fade-in\';\n            } else {\n                feedbackElement.textContent = `Incorrect. The correct answer is \${correctAnswer}.`;\n                feedbackElement.className = \'feedback feedback-incorrect fade-in\';\n                document.getElementById(\'solution\').style.display = \'block\';\n            }\n            \n            feedbackElement.style.display = \'block\';\n            updateScores();\n        }\n        \n        // Initialize the game\n        document.addEventListener(\'DOMContentLoaded\', function() {\n            setNewWord();\n            updateScores();\n            \n            document.getElementById(\'check-answer-btn\').addEventListener(\'click\', checkAnswer);\n            document.getElementById(\'new-word-btn\').addEventListener(\'click\', setNewWord);\n            \n            // Check answer when Enter key is pressed\n            document.getElementById(\'answer-input\').addEventListener(\'keyup\', function(event) {\n                if (event.key === \'Enter\') {\n                    checkAnswer();\n                }\n            });\n        });\n    </script>\n</body>\n</html>',
